import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';

const work = process.argv[2];
if (!work || !fs.existsSync(work)) throw new Error('Payments/advances/days patch: reconstructed work directory is required');

const archive = Buffer.from("", 'base64');
const expectedArchiveHash = '608e8b3e93c04349e3ce7c4c19ef7c2f8a2ed27bb015f814c727ed979ef6b4d7';
const actualArchiveHash = crypto.createHash('sha256').update(archive).digest('hex');
if (actualArchiveHash !== expectedArchiveHash) throw new Error('Payments/advances/days patch archive hash mismatch: ' + actualArchiveHash);

const archivePath = path.join(os.tmpdir(), 'transsalomao-payments-v2-' + process.pid + '.patch.xz');
const patchPath = path.join(os.tmpdir(), 'transsalomao-payments-v2-' + process.pid + '.patch');
fs.writeFileSync(archivePath, archive);
try {
  execFileSync('xz', ['-t', archivePath], { stdio: 'inherit' });
  const patch = execFileSync('xz', ['-dc', archivePath]);
  fs.writeFileSync(patchPath, patch);
  execFileSync('git', ['apply', '--no-index', '--unsafe-paths', '--whitespace=nowarn', patchPath], { cwd: work, stdio: 'inherit' });
} finally {
  fs.rmSync(archivePath, { force: true });
  fs.rmSync(patchPath, { force: true });
}

const checks = {
  'src/lib/calc.ts': '11c135bf945b97e33ecc3aa2058a7c62fd587e87dd21508656c63e961b7be044',
  'src/lib/api.ts': '2b234ff75d2230bb54189dfca79637101d915c0a94aea60bf6a4a8081d1efced',
  'src/lib/payment-accounting.ts': '0c0192d85efa2ee00fb9d9f0113850111f312b773f3f76e7106aaa26982ec36d',
  'src/routes/dono/despesas.tsx': 'ccab9c6518799deab3ca30ac80be17201062871e9c009e9644bbc7839e800f9d',
  'src/routes/dono/pagamentos.tsx': '21c794f02871d4272b902f2cdc7a4dc3aef904a92ae467c631ee926dc16ed513',
};
for (const [rel, expected] of Object.entries(checks)) {
  const file = path.join(work, rel);
  if (!fs.existsSync(file)) throw new Error('Payments/advances/days patch missing file: ' + rel);
  const actual = crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
  if (actual !== expected) throw new Error('Payments/advances/days patch file mismatch: ' + rel + ' => ' + actual);
}

console.log('[payments-advances-days] advances moved to Payments, commissions normalized, exact-day periods and payment allocation applied');
